// Verify the signed envelope before any work. Crypto only; no business logic.
const crypto = require('crypto');
const b = $json.body || {};
const ts = String(b.ts ?? '');
const payload = typeof b.payload === 'string' ? b.payload : '';
const sig = String(b.sig ?? '');
const expected = 'sha256=' + crypto.createHmac('sha256', $vars.MD_HMAC_SECRET).update(`${ts}.${payload}`).digest('hex');
const fresh = /^\d+$/.test(ts) && Math.abs(Date.now() / 1000 - Number(ts)) <= 300;
const a = Buffer.from(expected);
const g = Buffer.from(sig);
const sigOk = a.length === g.length && crypto.timingSafeEqual(a, g);
let parsed = null;
if (sigOk && fresh) {
  try { parsed = JSON.parse(payload); } catch (e) { parsed = null; }
}
const valid = parsed !== null && typeof parsed === 'object';
return [{ json: { valid, reason: valid ? 'ok' : !sigOk ? 'bad_signature' : !fresh ? 'stale' : 'bad_payload', payload: valid ? parsed : null } }];

// Split the API's messages into items and drop any idempotency key already handled in the last
// 48 h (the API retries a batch; the user must never get the same message twice).
const p = $('Verify envelope (HMAC)').first().json.payload || {};
const msgs = Array.isArray(p.messages) ? p.messages : [];
const store = $getWorkflowStaticData('global');
const now = Date.now();
store.seen = Object.fromEntries(Object.entries(store.seen || {}).filter(([, exp]) => exp > now));
const out = [];
for (const m of msgs) {
  const key = m.idempotency_key || m.notification_id;
  if (!key || store.seen[key]) continue;
  store.seen[key] = now + 48 * 3600 * 1000;
  out.push({ json: { ...m, event: p.event ?? null, event_id: p.event_id ?? null } });
}
return out;

// One receipt per message; paired-item lineage gives the original message.
const src = $('Split + drop duplicate keys').item.json;
const r = $json;
const failed = !!r.error;
const sentHere = src.channel === 'whatsapp' || src.channel === 'email';
return { json: {
  notification_id: src.notification_id,
  idempotency_key: src.idempotency_key ?? null,
  channel: src.channel,
  provider_message_id: r.messages?.[0]?.id ?? r.id ?? null,
  status: failed ? 'failed' : (sentHere ? 'sent' : 'backend_channel'),
  error_code: failed ? String(r.error?.code ?? r.error?.message ?? 'unknown').slice(0, 80) : null,
  at: new Date().toISOString()
} };

// Sign the API-66 receipts call (Margdarshak-Signature, fresh timestamp).
const crypto = require('crypto');
const body = JSON.stringify({ event: 'delivery_receipt', at: new Date().toISOString(), workflow: 'W02', execution_id: $execution.id, event_id: $('Verify envelope (HMAC)').first().json.payload.event_id ?? null, receipts: $json.receipts });
const ts = Math.floor(Date.now() / 1000).toString();
const v1 = crypto.createHmac('sha256', $vars.MD_HMAC_SECRET).update(`${ts}.${body}`).digest('hex');
return [{ json: { body, signature: `t=${ts},v1=${v1}`, idempotency_key: `w02-receipts:${$execution.id}`, receipts: $json.receipts } }];

// Keep only WhatsApp messages that were sent, for the 24 h 'seen?' check (reshape only).
const receipts = $('Sign receipts (HMAC)').first().json.receipts || [];
const ids = receipts.filter((r) => r.channel === 'whatsapp' && r.status === 'sent').map((r) => r.notification_id);
return ids.length ? [{ json: { notification_ids: ids } }] : [];

// Sign the 'seen?' check: one POST for the whole batch.
const crypto = require('crypto');
const body = JSON.stringify({ notification_ids: $json.notification_ids });
const ts = Math.floor(Date.now() / 1000).toString();
const v1 = crypto.createHmac('sha256', $vars.MD_HMAC_SECRET).update(`${ts}.${body}`).digest('hex');
return [{ json: { body, signature: `t=${ts},v1=${v1}` } }];

// Reshape: the ids the backend asked to fall back on (email / web push sent by the backend).
const results = Array.isArray($json.results) ? $json.results : [];
const ids = results.filter((r) => r.action === 'request_fallback').map((r) => r.notification_id);
if (ids.length === 0) return [];
const crypto = require('crypto');
const body = JSON.stringify({ event: 'request_fallback', at: new Date().toISOString(), workflow: 'W02', notification_ids: ids });
const ts = Math.floor(Date.now() / 1000).toString();
const v1 = crypto.createHmac('sha256', $vars.MD_HMAC_SECRET).update(`${ts}.${body}`).digest('hex');
return [{ json: { body, signature: `t=${ts},v1=${v1}`, idempotency_key: `w02-fallback:${$execution.id}` } }];
